let dialog=null,onCancel=null;
export function progressOpen(title,cancel){if(!document.createElement)return;progressClose();dialog=document.createElement('dialog');dialog.className='progress-dialog';dialog.setAttribute('aria-label',title);dialog.innerHTML='<h2></h2><p class="progress-stage" role="status" aria-live="polite"></p><progress aria-label="Task progress" max="100"></progress><p class="progress-percent"></p><button class="ghost">Cancel</button>';dialog.querySelector('h2').textContent=title;onCancel=cancel;const stop=()=>onCancel?.();dialog.querySelector('button').onclick=stop;dialog.oncancel=e=>{e.preventDefault();stop();};document.body.append(dialog);dialog.showModal();progressUpdate('Preparing…');}
export function progressUpdate(stage,fraction){if(!dialog)return;dialog.querySelector('.progress-stage').textContent=stage;const bar=dialog.querySelector('progress'),label=dialog.querySelector('.progress-percent');if(Number.isFinite(fraction)){const n=Math.round(Math.max(0,Math.min(1,fraction))*100);bar.value=n;label.textContent=n+'%';}else{bar.removeAttribute('value');label.textContent='Working…';}}
export function progressClose(){if(dialog){dialog.close();dialog.remove();dialog=null;}onCancel=null;}
